#include <acutest.h>
#include <gkyl_gyrokinetic_priv.h>
#include <gkyl_array_rio.h>

static void
mapc2p(double t, const double *xc, double *xp, void *ctx)
{
  for (int d = 0; d < 3; ++d) xp[d] = xc[d];
}

static void
bfield(double t, const double *xc, double *out, void *ctx)
{
  out[0] = out[1] = 0.0;
  out[2] = 1.0;
}

static void
one(double t, const double *xc, double *out, void *ctx)
{
  out[0] = 1.0;
}

static void
zero(double t, const double *xc, double *out, void *ctx)
{
  out[0] = 0.0;
}

static void
check_diagnostics(int mask, bool is_static)
{
  struct gkyl_gk inp = {
    .name = "ctest_gk_time_rate", .cdim = 1, .lower = {-2.0}, .upper = {2.0},
    .cells = {4}, .poly_order = 1, .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
    .geometry = {.geometry_id = GKYL_GEOMETRY_MAPC2P, .mapc2p = mapc2p, .bfield_func = bfield},
    .num_periodic_dir = 1, .periodic_dirs = {0}, .num_species = 1,
    .species = {{.name = "ion", .charge = 1.0, .mass = 1.0, .vdim = 2,
      .lower = {-4.0, 0.0}, .upper = {4.0, 6.0}, .cells = {4, 4},
      .polarization_density = 1.0, .is_static = is_static,
      .projection = {.proj_id = GKYL_PROJ_MAXWELLIAN_PRIM,
        .density = one, .temp = one, .upar = zero}}},
    .field = {.is_static = true, .kperpSq = 1.0}
  };
  for (int d = 0; d < GKYL_GK_TIME_RATE_DIAGNOSTIC_NUM; ++d)
    if (mask & (1 << d))
      inp.species[0].time_rate_diagnostics[inp.species[0].num_time_rate_diagnostics++] = d;
  gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&inp);
  gkyl_gyrokinetic_app_apply_ic(app, 0.0);
  struct gk_species *gks = &app->species[0];
  // An actual RK step exercises disabled callbacks and completion of the moments.
  struct gkyl_update_status st = gkyl_gyrokinetic_update(app, 0.001);
  TEST_CHECK(st.success);
  TEST_CHECK(app->stat.nfeuler == 3);
  if (!is_static && (mask & ~1)) {
    // Manufacture opposite changes in adjacent cells to test cancellation and
    // absolute-before-sum independently of the PDE and the diagnostic code.
    gk_species_calc_int_mom_dt(app, gks, 0.25, gks->fdot_mom_old);
    struct gkyl_array *old = gkyl_array_new(GKYL_DOUBLE, gks->fdot_mom_old->ncomp, app->local_ext.volume);
    gkyl_array_copy(old, gks->fdot_mom_old);
    struct gkyl_range_iter iter;
    gkyl_range_iter_init(&iter, &gks->local);
    while (gkyl_range_iter_next(&iter)) {
      double *f = gkyl_array_fetch(gks->f, gkyl_range_idx(&gks->local, iter.idx));
      double factor = iter.idx[0] % 2 ? 1.25 : 0.75;
      for (int k = 0; k < gks->basis.num_basis; ++k) f[k] *= factor;
    }
    gk_species_calc_int_mom_dt(app, gks, 0.25, gks->fdot_mom_new);
    gk_species_calc_fdot_mom(app, gks);
    double signed_sum[4] = {0}, abs_sum[4] = {0};
    gkyl_range_iter_init(&iter, &app->local);
    while (gkyl_range_iter_next(&iter)) {
      long loc = gkyl_range_idx(&app->local, iter.idx);
      const double *before = gkyl_array_cfetch(old, loc);
      const double *actual = gkyl_array_cfetch(gks->fdot_mom_new, loc);
      for (int m = 0; m < 4; ++m) {
        double expected = before[m] * (iter.idx[0] % 2 ? 0.25 : -0.25);
        TEST_CHECK(fabs(actual[m] - expected) < 1e-12 * fmax(1.0, fabs(expected)));
        signed_sum[m] += expected;
        abs_sum[m] += fabs(expected);
      }
    }
    gk_species_calc_integrated_mom(app, gks, 0.25);
    double vals[4];
    if (mask & (1 << GKYL_GK_TIME_RATE_DIAGNOSTIC_FDOT_INTEGRATED_MOMENTS)) {
      gkyl_dynvec_getlast(gks->fdot_integ_diag, vals);
      for (int m = 0; m < 4; ++m) TEST_CHECK(fabs(vals[m] - signed_sum[m]) < 1e-12);
    }
    if (mask & (1 << GKYL_GK_TIME_RATE_DIAGNOSTIC_FDOT_ABS_INTEGRATED_MOMENTS)) {
      gkyl_dynvec_getlast(gks->fdot_abs_integ_diag, vals);
      for (int m = 0; m < 4; ++m) TEST_CHECK(gkyl_compare(vals[m], abs_sum[m], 1e-12));
      TEST_CHECK(vals[0] > 0.0);
    }
    gk_species_write_mom(app, gks, 0.25, 1);
    for (int d = 3; d <= 4; ++d) {
      if (!(mask & (1 << d))) continue;
      char filename[128];
      snprintf(filename, sizeof filename, "ctest_gk_time_rate-ion_%s_M0M1M2parM2perp_1.gkyl", d == 3 ? "fdot" : "fdot_abs");
      struct gkyl_rect_grid grid;
      struct gkyl_array *written = gkyl_grid_array_new_from_file(&grid, filename);
      TEST_CHECK(written != NULL);
      if (written) {
        gkyl_range_iter_init(&iter, &app->local);
        long cell = 0;
        while (gkyl_range_iter_next(&iter)) {
          const double *expected = gkyl_array_cfetch(gks->fdot_mom_new, gkyl_range_idx(&app->local, iter.idx));
          const double *actual = gkyl_array_cfetch(written, cell++);
          for (int m = 0; m < 4; ++m) {
            double coeff = expected[m] * sqrt(2.0) / app->grid.dx[0];
            if (d == 4) coeff = fabs(coeff);
            TEST_CHECK(fabs(actual[m] - coeff) < 1e-12 * fmax(1.0, fabs(coeff)));
          }
        }
        gkyl_array_release(written);
      }
      remove(filename);
    }
    gkyl_array_release(old);
  }
  gkyl_gyrokinetic_app_release(app);
}

static void
test_diagnostics(void)
{
  check_diagnostics(0, false);
  for (int d = 0; d < GKYL_GK_TIME_RATE_DIAGNOSTIC_NUM; ++d) check_diagnostics(1 << d, false);
  check_diagnostics(31, false);
  check_diagnostics(31, true);
}

TEST_LIST = {{"gk_time_rate_diagnostics", test_diagnostics}, {NULL, NULL}};
